SET @process = 'Se elimina SP ccsp_MetaWAOutboundTemplates'
SET @sql = 'if exists (select * from sys.procedures where name = N''ccsp_MetaWAOutboundTemplates'')
    begin
        DROP PROCEDURE ccsp_MetaWAOutboundTemplates;
    end'
