    SET @process = 'Drop procedure ccsp_DLRgetDialPrefix'
    SET @sql = 'IF EXISTS (SELECT * FROM sysobjects WHERE name=''ccsp_DLRgetDialPrefix'')
        BEGIN
            DROP PROCEDURE dbo.ccsp_DLRgetDialPrefix
        END'
